-- ============================================================================
-- v144: 语数英三科 — 四川对口升学真题命题风格深度对齐
-- 基于2022-2025年真题调研：
--   英语：试卷结构/题型分布/高频考点/真题排布规律
--   数学：各模块真实分值占比/解答题顺序/高频失分点
--   语文：阅读选材倾向/作文命题方向/文言考查层次
-- ============================================================================
SET NAMES utf8mb4;

-- ============================================================
-- PART 1: 英语[职高] — 真题命题风格深度注入
-- 关键发现：
--   1. "语言应用"非传统完形，而是多模态语篇(标识牌/广告/票务)
--   2. 单选15题有固定的考点排布规律(情景→冠词→主谓一致→...→倒装)
--   3. 阅读5篇×4题，话题按"校园→科技→社会→人文→实用"排序
--   4. 写作以应用文+话题写作为主，不考传统议论文
-- ============================================================

-- 1.1 考纲注入：试卷结构 + 真题考点分布表 + 命题关键词
UPDATE exam_syllabus SET content = CONCAT(content, '\n\n## 真题命题风格与考查规律\n\n### 一、试卷结构（2022-2025年稳定版）\n\n| 卷别 | 题型 | 题量 | 分值 | 单题分 |\n|------|------|------|------|--------|\n| 第I卷(客观) | 单项选择 | 15题 | 15分 | 1分/题 |\n| 第I卷(客观) | 语言应用 | 10题 | 15分 | 1.5分/题 |\n| 第I卷(客观) | 阅读理解 | 5篇×4题=20题 | 40分 | 2分/题 |\n| 第II卷(主观) | 补全对话 | 5题 | 5分 | 1分/题 |\n| 第II卷(主观) | 翻译 | 5题 | 10分 | 2分/题 |\n| 第II卷(主观) | 书面表达 | 1题 | 15分 | — |\n\n### 二、单项选择题 — 15题考点排布规律（真题验证）\n\n根据近年真题试卷统计，15道单选题的考查范围基本固定为：\n\n| 题号 | 考点 | 考查频率 | 典型命题形式 |\n|------|------|----------|-------------|\n| 1 | 情景交际 | 必考 | 日常对话补全（邀请/感谢/道歉/建议） |\n| 2 | 冠词 | 高频 | 定冠词the vs 不定冠词a/an；零冠词判断 |\n| 3 | 代词 | 高频 | it/one/that/those替代；不定代词some/any/none |\n| 4 | 介词 | 必考 | 时间介词in/on/at；短语介词搭配 |\n| 5 | 主谓一致 | 高频 | together with/except后的谓语形式；就近原则 |\n| 6 | 动词短语辨析 | 必考 | look/take/make/put/get等+介词的短语辨析 |\n| 7 | 连词/状语从句 | 必考 | though/although/if/when/since/so...that |\n| 8 | 反意疑问句/感叹句 | 轮考 | 复反疑问句的助动词选择；What vs How |\n| 9 | 动词词义辨析 | 必考 | 同义词在语境中的区分(spend/cost/pay等) |\n| 10 | 情态动词 | 必考 | must/can/may/should基本用法；must have done推测 |\n| 11 | 非谓语动词 | 必考 | to do vs doing vs done在句中的正确形式 |\n| 12 | 名词性从句/宾语从句 | 必考 | 陈述语序；whether vs if；what vs that |\n| 13 | 定语从句 | 必考 | which/that/who关系词选择；非限制性(逗号) |\n| 14 | 虚拟语气/倒装 | 轮考 | If had done...would have done; Only+状语倒装 |\n| 15 | 综合/形容词副词辨析 | 必考 | -ed vs -ing分; 比较级最高级 |\n\n### 三、"语言应用"题型 — 多模态语篇（四川特色）\n> 注：该题型不是传统完形填空，而是通过真实语料图片考查信息提取\n\n| 常考素材 | 示例 | 能力要求 |\n|----------|------|----------|\n| 公共标识牌 | 交通标志/安全标识 | 理解标识含义，匹配中英文说明 |\n| 广告传单 | 促销海报/活动通知 | 提取价格/时间/地点/条件信息 |\n| 票务信息 | 机票/车票/电影票 | 读取日期/时间/座位/票价 |\n| 日程安排 | 会议议程/课程表 | 理解时间和活动对应关系 |\n| 地图示意 | 校园平面图/街区图 | 方位判断和路线理解 |\n\n### 四、阅读理解 — 5篇话题排序规律\n\n| 篇序 | 话题类型 | 字数 | 题数 | 难度 | 常考话题举例 |\n|------|----------|------|------|------|-------------|\n| A篇 | 校园生活 | 150-200 | 4 | 易 | 校园活动通知/课程介绍/学生故事 |\n| B篇 | 社会文化 | 150-200 | 4 | 易 | 节日习俗/文化差异/社区服务 |\n| C篇 | 科技常识 | 200-250 | 4 | 中 | 环保技术/网络发展/健康科普 |\n| D篇 | 人物故事 | 200-250 | 4 | 中 | 名人传记/励志经历/历史人物 |\n| E篇 | 实用说明 | 200-250 | 4 | 较难 | 操作指南/产品说明/调查报告 |\n\n### 五、写作 — 两大题型命题规律\n\n**应用文（常考形式）：**\n| 文体 | 分值 | 字数 | 命题要点 |\n|------|------|------|----------|\n| 书信/电子邮件 | 15分 | 80-100词 | 感谢/邀请/建议/申请四种信体轮考 |\n| 通知 | 15分 | 60-80词 | 书面/口头两种形式，四要素完整 |\n| 便条/启事 | 15分 | 50-70词 | 格式简短，信息准确 |\n\n**评分关键词：** 格式完整 40% + 内容要点 30% + 语言准确性 30%\n\n### 六、翻译 — 命题选材规律\n\n英译汉（3题6分）：选取含定语从句/非谓语/被动语态的复合句\n汉译英（2题4分）：选取考纲高频动词搭配和基本句型\n不考长篇翻译，均为单句翻译\n') WHERE id = 5;

-- 1.2 L4节点注入：真题关键词 + 命题信号词 + 常见陷阱
-- 动词辨析节点 -- 真题中最常见的"花费""提供"考查形式
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=24 AND name='考试核心500词' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n【对口径：真题考查形式】\n单选/完形以"题干暗示"方式出题——给出具体语境(对话/叙事)，要求选恰当的"花费/提供"动词。例如："How much did the coat ___ you?"→答案cost(物作主语)；"He ___ me a lift to the station."→答案offered(主动提供)。\n\n【命题信号词】\n- spend→人+spend+时间/金钱+on sth/(in) doing\n- cost→物+cost+人+金钱(主语=物)\n- take→It+takes+人+时间+to do\n- pay→人+pay+金钱+for+物\n- offer→offer sb sth / offer to do(主动提供)\n- provide→provide sb with sth / provide sth for sb\n\n【真题陷阱】\n"这支笔花了我十元"→I spent ten yuan on the pen. / The pen cost me ten yuan. / I paid ten yuan for the pen. 三句话都对但动词不同！')
WHERE parent_id=@l3 AND name='动词辨析（spend/cost/take/pay/offer/provide）[中等]';

-- 时态语态节点 — 真题考查形式
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=24 AND name='时态语态' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n【对口径：真题命题规律】\n时态语态考查约占单选15题中的3-4题，是所有语法考点中频次最高的模块。真题出题特点：题干含明确的时间状语(标志词)，选项为同一动词的四种时态形式。\n\n【真题标志词速查表】\n- 一般现在时→often, usually, every day, always, never\n- 一般过去时→yesterday, last week, in 2020, ago, just now\n- 一般将来时→tomorrow, next week, in the future\n- 现在进行时→now, right now, Look!, Listen!\n- 现在完成时→already, yet, ever, never, since, for, so far, recently\n- 过去完成时→by the time, before+过去时间, after+过去完成\n- 过去进行时→at this time yesterday, when...came in\n\n【真题陷阱】\n1. "for+时间段"不能与短暂动词连用→He has borrowed the book for a week.（×）应改为has kept\n2. 现在完成时不能与具体过去时间连用→I have seen him yesterday（×）应改为saw\n3. when从句动词短暂用过去进行时主句→He was reading when I came in（√）')
WHERE parent_id=@l3 AND name='一般现在时 [基础]' AND content NOT LIKE '%真题标志词%';

-- 情景交际 — 真题补充
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=24 AND name='情景交际' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n【对口径：真题必考题·单选第1题】\n情景交际固定为四川对口升学英语单选第1题，考查日常对话的得体应答。近年真题涉及：邀请与请求(约40%)、感谢与道歉(约25%)、建议与劝告(约20%)、问路与指路(约15%)。\n\n【真题高频陷阱】\n1. "Would you mind opening the window?"回答"Yes"表示介意(不同意)，"No/Not at all"表示不介意(同意)——与中文思维完全相反！\n2. "Thank you for helping me."回答不可用"No"，必须用"You''re welcome/My pleasure/Not at all"\n3. "Must I finish it today?"否定回答是"No, you needn''t/don''t have to"，不能用"No, you mustn''t"(mustn''t=禁止)')
WHERE parent_id=@l3 AND name='邀请与请求 [基础]';

-- ============================================================
-- PART 2: 数学[职高] — 真题命题深度注入
-- 关键发现：
--   1. 选择题60分(40%)+填空20分+解答题70分(60%)
--   2. 解析几何18%最大模块，立体几何10%
--   3. 解答题顺序基本固定：函数→三角→数列/解析几何→立几/综合
--   4. "生活中的数学应用"约15%分布在各模块
-- ============================================================

-- 2.1 数学考纲增强：真题分值分布 + 解答题排布规律
UPDATE exam_syllabus SET content = CONCAT(content, '\n\n## 真题命题风格与考查规律\n\n### 一、真实分值分布（近年真题统计）\n\n| 模块 | 考纲占比 | 约分值 | 典型题型 |\n|------|----------|--------|----------|\n| 集合 | 5-8% | 7-12分 | 选择1-2题 + 填空(判断关系/运算) |\n| 不等式 | 5-10% | 7-15分 | 选择1-2题 + 填空(一元二次/绝对值) |\n| 函数 | 10-12% | 15-18分 | 选择2题 + 解答题1道(定义域/奇偶/单调/最值) |\n| 指数对数 | 5-8% | 7-12分 | 选择1-2题(图像/性质/运算) |\n| 三角函数 | 14% | 21分 | 选择2题 + 填空1题 + 解答题1道(公式化简/解三角形) |\n| 数列 | 8-10% | 12-15分 | 选择1-2题 + 解答题1道(等差/等比/求和) |\n| 平面向量 | 5-8% | 7-12分 | 选择1-2题 + 填空(坐标/数量积/平行垂直) |\n| 立体几何 | 10% | 15分 | 选择1题 + 填空1题 + 解答题1道(表体积/线面关系) |\n| 解析几何 | 18% | 27分 | 选择2题 + 填空1题 + 解答题1道(直线/圆/圆锥曲线) |\n| 概率统计 | 5-8% | 7-12分 | 选择1-2题(古典概型/排列组合) |\n| 导数初步 | 约5% | 7-8分 | 选择1题 + 解答题1道(选考·求导/切线/单调) |\n\n### 二、解答题排布规律（真题验证）\n\n近几年四川对口升学数学解答题顺序基本固定：\n\n| 题号 | 分值 | 常考模块 | 典型考查形式 | 难度 |\n|------|------|----------|-------------|------|\n| 第21题 | 12分 | 函数 | 求定义域+判断奇偶性+证明单调性+闭区间最值 | 中等 |\n| 第22题 | 12分 | 三角函数 | 化简三角式+求周期/最值+解三角形(正弦/余弦定理) | 中等 |\n| 第23题 | 12分 | 数列/解析几何 | 等差/等比通项+求和；直线方程+圆+位置关系 | 中等 |\n| 第24题 | 12分 | 解析几何 | 椭圆/双曲线标准方程+几何性质+综合应用 | 较难 |\n| 第25题 | 12分 | 立几/解析综合 | 体积表面积计算+线面关系判定 | 中等 |\n| 第26题 | 10分 | 函数应用/导数 | 实际建模(利润/面积/距离最值)或导数(切线/单调区间/极值) | 较难 |\n\n### 三、选择题高频陷阱类型\n\n| 陷阱类型 | 典型例子 | 正确解法 |\n|----------|----------|----------|\n| 集合符号混淆 | 选"∈"还是"⊆"？ | N⊆Z(N是Z的子集)；2∈N(2是N的元素)。集合之间用⊆，元素与集合用∈ |\n| 不等式符号反转 | 两边同乘负数忘记变号方向 | 乘/除负数前先判断→ 负数的乘除会改变不等号方向 |\n| 定义域条件遗漏 | 只考虑分母≠0漏了根号下≥0 | 三步法：分母≠0 + 偶次根号≥0 + 对数真数>0，全列再取交集 |\n| 指数对数运算混淆 | a^m·a^n误写为a^{mn} | a^m·a^n=a^{m+n}（乘→加指数）；(a^m)^n=a^{mn}（幂→乘指数）|\n| 三角函数象限符号 | 第二象限sin正？cos正？ | 口诀"一全二正弦三切四余弦"——一全正/二正弦/三正切/四余弦 |\n| 错位相减q=1忘讨论 | 等比求和直接用a1(1-q^n)/(1-q) | 必须先检查q是否=1！q=1时Sn=na1不能代公式 |\n| 锥体体积漏乘1/3 | 圆锥体积写成πr²h | 锥体=1/3×S底×h，和等底等高柱体体积比为1:3 |\n| 余弦定理a²后漏带2bc | 写成a²=b²+c²-cosA | 正确：a²=b²+c²-2bc·cosA（减号+系数2都不能少）|\n| 排列组合混淆 | 做题不判断"有序"还是"无序" | 取出元素后调换顺序→有影响=排列A；无影响=组合C |\n| 古典概型基本事件数错 | 扔两枚硬币基本事件数算成3 | {正正,正反,反正,反反}→4个！"一正一反"不是基本事件是复合事件|\n\n### 四、三角函数 — 真题命题特点（分值最高模块）\n\n| 题型 | 分值 | 频率 | 考查内容 |\n|------|------|------|----------|\n| 选择题 | 2题10分 | 必考 | 任意角三角函数值符号；诱导公式化简；正弦型函数图像性质 |\n| 填空题 | 1题5分 | 必考 | 两角和差/二倍角公式化简求值 |\n| 解答题 | 1题12分 | 必考 | 周期和最值求解+正弦/余弦定理解三角形 |\n\n**真题典型解答题模板：**\n已知f(x)=asinx+bcosx或sinxcosx形式→用辅助角公式或二倍角化简→求周期T=2π/ω→求最值(正弦函数最值±1)→第二问给出三角形的边角条件→用正弦/余弦定理求边/角。\n') WHERE id = 10;

-- 2.2 数学L4节点注入：对口径真题考查特征
-- 函数考点
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='函数概念' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n【对口径：解答题第21题常考】\n函数解答题通常第1问求定义域(3分)→第2问判断/证明奇偶性或单调性(4分)→第3问求闭区间最值(5分)。三步得分必须全部拿到。')
WHERE parent_id=@l3 AND name LIKE '%函数定义%' AND content NOT LIKE '%对口径%';

-- 三角函数考点
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='三角函数的公式' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n【对口径：解答题第22题必考】\n三角解答题12分的得分策略：第1步化简(4分·诱导公式+同角公式+两角和差)→第2步求周期T=2π/ω和最值(4分·y=Asin(ωx+φ)的ω决定周期)→第3步解三角形(4分·给边角条件用正弦或余弦定理)。公式必须准确默写，一个公式错误导致全题0分！\n\n【真题送分点】\n周期公式T=2π/|ω|，最值就是正弦前面的系数±A。这两问只要正确化简出A和ω就能拿分，不需要太高技巧。')
WHERE parent_id=@l3 AND name LIKE '%诱导公式%' AND content NOT LIKE '%对口径%';

-- 解析几何考点
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='直线与圆的位置关系' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n【对口径：解答题第23或24题常考】\n解析几何解答题常以"直线与圆的综合题"形式出现，通常是：已知直线方程和圆方程→求圆心和半径(3分)→求圆心到直线距离(3分)→判断位置关系或求弦长(3分)→求切线方程(3分)。\n\n【真题送分细节】\n1. 标准方程(x-a)²+(y-b)²=r²的圆心坐标符号不要写反——(x-2)²圆心是(2,0)不是(-2,0)\n2. 圆的一般式配方时，常数项是D²/4+E²/4-F，不是直接移项\n3. 点到直线距离公式|Ax+By+C|/√(A²+B²)中分子别忘了加绝对值！')
WHERE parent_id=@l3 AND name LIKE '%直线与圆的位置关系%' AND content NOT LIKE '%对口径%';

-- ============================================================
-- PART 3: 语文[职高] — 真题命题深度注入
-- 关键发现：
--   1. 阅读与写作各占40%，合计80%
--   2. 现代文分社科类(选择题)和文学类(简答题)
--   3. 作文以材料作文+议论文为主
--   4. 大作文常考主题：工匠精神/才艺天赋/法治/勇敢/积累坚持/梦想
-- ============================================================

-- 3.1 语文考纲增强：真题阅读选材+作文命题方向+文言考查
UPDATE exam_syllabus SET content = CONCAT(content, '\n\n## 真题命题风格与考查规律\n\n### 一、试卷结构（近年稳定版）\n\n| 模块 | 分值 | 题型 | 说明 |\n|------|------|------|------|\n| 基础知识与运用 | 约20%(30分) | 选择为主 | 字音字形/词语运用/病句辨析/修辞 |\n| 现代文阅读 | 约40%(60分) | 选择+简答 | 社科类(选择题)+文学类(简答题) |\n| 文言文阅读 | 约8%(12分) | 选择+填空+翻译 | 实词释义/虚词用法/句式辨析/句子翻译 |\n| 写作 | 约32%(48分) | 应用文15分+大作文33分 | 应用文格式+材料作文/话题作文 |\n\n### 二、现代文阅读 — 社科类选材与题型\n\n**常考文体与话题：**\n| 文体 | 话题举例 | 命题形式 |\n|------|----------|----------|\n| 科技说明文 | 人工智能、5G通信、绿色能源 | 三道选择题：理解句意+筛选信息+推断结论 |\n| 社科论述文 | 文化传承、教育理念、社会现象分析 | 三道选择题：论点判断+论据识别+论证逻辑 |\n\n**【真题解题铁律】社科类选择题的六大错误类型：**\n1. 偷换概念——把文中A特点偷换成B特点\n2. 扩大/缩小范围——将"部分学者认为"说成"所有学者认为"\n3. 因果倒置——把"因为A所以B"说成"因为B所以A"\n4. 无中生有——文章根本没提的选项内容\n5. 混淆时态——把"将要做"说成"已经做"\n6. 绝对化表述——含"全部/必然/唯一/根本"的选项大概率错误\n\n### 三、现代文阅读 — 文学作品选材与主观题\n\n**近年选材倾向：**\n- 抒情散文（情感真挚、语言优美的人文题材）\n- 精短小说（情节简单、人物鲜明、意蕴深刻的微型小说）\n\n**【文学作品阅读4道简答题模板：】**\n第1题"理解文中画线句的含义"(4分)→答题步骤：表面义+深层义+作者情感/写作意图\n第2题"分析第X段的作用"(4分)→从结构作用(承上启下/铺垫/照应)+内容作用(点题/深化主旨)\n第3题"文中某人物/某事物有什么特点"(4分)→找文中对该人物/事物的所有描写，逐条概括\n第4题"探究文章主旨/标题含义"(6分)→2分表层(字面意思)+2分深层(作者想表达什么)+2分升华(对读者的启示)\n\n### 四、文言文阅读 — 命题范围\n\n**规定背诵篇目（附2）：**\n《诗经》二首(静女/采薇)、孟子《寡人之于国也》、荀况《劝学》、韩愈《师说》、李白《将进酒》、苏轼《念奴娇·赤壁怀古》、白居易《琵琶行》(节选)\n\n**【高频考查关键词：】**\n| 类别 | 考查点 | 真题示例 |\n|------|--------|----------|\n| 实词 | 一词多义 | "亡"可解为"逃跑/丢失/灭亡/同无"(视语境而定) |\n| 虚词 | 之/其/以/而/于/为六字 | "之"字用法最多(代词/结构助词/动词/取独) |\n| 句式 | 判断句/被动句/倒装/省略 | "客有吹洞箫者"→定语后置 |\n| 活用 | 名词作动词/状语；使动/意动 | "以其乃华山之阳名之也"→"名"名词作动词"命名" |\n| 翻译 | 直译为主，意译为辅 | 五字法：留(国名/人名/官职不译)+补(省略成分)+换(古今异义)+调(倒装调序)+删(发语词/句末语气词) |\n\n### 五、作文命题 — 材料作文主题分析\n\n**【近年真题作文主题汇总：】**\n| 年份 | 材料内容 | 核心主题 | 文体要求 |\n|------|----------|----------|----------|\n| 近年常考 | 毛竹四年扎根后疯狂生长 | 厚积薄发/沉淀/积累 | 议论文 |\n| 近年常考 | 方孝孺《深虑论》节选 | 忧患意识/深谋远虑 | 议论文 |\n| 近年常考 | 青年工匠获世界技能大赛金牌 | 工匠精神/精益求精 | 议论文 |\n| 近年常考 | 基层劳动者坚守岗位的故事 | 平凡岗位/社会责任 | 议论文 |\n| 近年常考 | 面对困境保持勇气的话题 | 勇敢/坚韧/乐观 | 记叙文或议论文 |\n\n**【作文高分"三要素"：】**\n1. 审题准确(2分)：以材料关键词为"抓手"，首段必须点材料、亮观点\n2. 结构清晰(4分)：并列式(三段并列论证)/递进式(是什么→为什么→怎么做)/对照式(正反对比论证)\n3. 素材具体(3分)：用真实人物事例而非空洞说理，每段至少一个具体案例\n\n**【作文常见"失分项"：】**\n- 离题(扣30%以上)：没有抓住材料核心词，另起话题\n- 空话(扣10-15%)："要努力""要有梦想"这类空洞口号没有具体内容\n- 文体不清(扣10-20%)：要求议论文却写成抒情散文或流水账\n') WHERE id = 4;

-- 3.2 语文L4节点注入：真题阅读技巧 + 作文素材关键词
-- 应用文写作节点 — 注入评分细则
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND name='应用文写作' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n【对口径：应用文评分表】\n| 评分项 | 分值 | 得分要点 | 扣分项 |\n|--------|------|----------|--------|\n| 格式规范 | 约50% | 标题居中+落款完整+日期正确 | 漏写标题扣2分/漏署名扣2分 |\n| 语言得体 | 约30% | 语气恰当+用词准确 | 口语化/随意表达扣分 |\n| 内容要素 | 约20% | What/When/Where/Who全有 | 漏一要素扣1-2分 |\n\n【真题提醒】应用文不求文采只求规范！格式对=得分大半，语言再美格式不对也丢分。')
WHERE parent_id=@l3 AND name LIKE '%应用文写作%' AND level=3 AND content NOT LIKE '%对口径%';

UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n【对口径：真题高频命题关键词】\n近五年四川对口升学作文材料中反复出现的关键词："工匠精神""精益求精""传承""坚守""创新""责任""勇敢""积累""坚持""奉献""理想"。这些词构成命题的核心概念网。\n\n【素材运用技巧】\n每篇议论文至少用2-3个具体人物事例。常用素材库：\n- 大国工匠类：火箭"心脏"焊接人高凤林、火药微整形师徐立平、宣纸捞纸工周东红\n- 科学家类：袁隆平(扎根稻田/坚持一生)、屠呦呦(190次失败/青蒿素)、钱学森(放弃美国高薪回国)\n- 普通人坚守类：乡村教师张玉滚(扎根深山18年)、快递小哥当选"全国劳动模范"\n- 逆境成长类：司马迁(宫刑后写史记)、贝多芬(失聪后创作第九交响曲)')
WHERE parent_id=@l3 AND name LIKE '%话题写作%' AND level=3 AND content NOT LIKE '%对口径%';

-- 文言文实词节点
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND name='文言文阅读(二)' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n【对口径：文言文翻译"五字法"真题实操】\n留：国名、人名、官职、器物名不翻译（如"沛公"→直接写"沛公"不翻"沛县公"）\n补：补充省略的主语或宾语（如"（）见渔人，乃大惊"→补"村人"）\n换：古今异义词用现代汉语替换（如"妻子"→"妻子和儿女"）\n调：倒装句调回正常语序（如"何厌之有"→"有何厌"）\n删：发语词/句末语气词删除（如"夫"、"也"、"矣"不译出）\n\n【真题必背120实词高频前20：】\n"之/其/以/而/于/为/乃/则/因/且/何/安/孰/胡/奚/盍/所/者/也/焉"\n其中"之""其""以""而""于""为"六个虚词考频最高，务必掌握每个词的3-5种用法。')
WHERE parent_id=@l3 AND name LIKE '%文言实词%' AND content NOT LIKE '%对口径%';

-- 现代文阅读手法节点
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND name='现代文阅读(一)' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = CONCAT(content, '\n\n【对口径：文学作品主观题答题模板】\n**题型一："画线句的含义是什么？"(4分)**\n模板：① 表面意思(这句话在文字层面说什么)→② 深层含义(在上下文语境中的延伸义)→③ 情感/主旨(作者借这句话表达什么)\n\n**题型二："第X段在文中的作用是什么？"(4分)**\n模板：① 结构作用(承上启下/引出下文/总结上文/铺垫/照应)→② 内容作用(点明题旨/深化主题/抒发感情/设置悬念)\n\n**题型三："文章题目/标题的含义和作用？"(6分)**\n模板：① 表层意思(字面义·1分)→② 深层含义(象征义/比喻义·2分)→③ 主旨关联(对表达文章主旨的作用·2分)→④ 读者效果(引发思考/设置悬念/激发兴趣·1分)\n\n【选择题排除法——六大错误类型一键排除：】\n偷换概念→删 | 扩大缩小范围→删 | 因果倒置→删 | 无中生有→删 | 混淆时态→删 | 绝对化表述→删')
WHERE parent_id=@l3 AND name LIKE '%筛选信息%' AND content NOT LIKE '%对口径%';

SELECT 'v144: Real-exam alignment optimization completed' AS result;
